import {Vector3,Euler} from '../../lib/three.core.js';

// Collision approximation for seam-rail.glb, generated by
// cc/hotwet-burner-designs-1024:c9915c0a1 examples/burner-designs/generate.mjs.
// Metres, Y up, floor origin. These ten separate boxes retain the open slot.
// Small bevels (up to 4 mm), fasteners and the feed fitting are not represented.
export const seamRailSupportBoxes = [
  {name:'Left foot',size:[.075,.025,.20],position:[-.22,.0125,0]},
  {name:'Right foot',size:[.075,.025,.20],position:[.22,.0125,0]},
  {name:'Plenum base',size:[.62,.026,.112],position:[0,.042,0]},
  {name:'Front wall',size:[.62,.060,.018],position:[0,.081,-.052]},
  {name:'Back wall',size:[.62,.060,.018],position:[0,.081,.052]},
  {name:'Left end',size:[.020,.072,.112],position:[-.30,.09,0]},
  {name:'Right end',size:[.020,.072,.112],position:[.30,.09,0]},
  {name:'Slot floor',size:[.58,.006,.07],position:[0,.056,0]},
  {name:'Front lip',size:[.58,.025,.045],position:[0,.1115,-.0315]},
  {name:'Back lip',size:[.58,.025,.045],position:[0,.1115,.0315]},
];

// Uses the ordinary editor operations. Supports stay editable, participate in
// the assembly's transforms, and save with the scene; hiding is viewport-only.
// The caller explicitly selects this known model. No automatic mesh inference.
export function addSeamRailWaterSupport(host,railId) {
  const api=host.kaminosSceneAuthoring,state=api.read();
  const rail=state.objects.find(o=>o.id===railId);
  if(!rail?.transform)throw Error('Choose the authored Seam rail mesh');
  const prefix='Rail water support · ';
  let group=state.groups.find(g=>g.objectIds.includes(railId));
  if(group?.objectIds.some(id=>state.objects.some(o=>o.id===id&&o.label?.startsWith(prefix))))throw Error('This assembly already has rail water support');
  const {position,rotation,scale}=rail.transform;
  if(![...position,...rotation,...scale].every(Number.isFinite)||scale.some(v=>v===0))throw Error('Rail support requires a finite, nonzero pose');
  const created=[];
  for(const part of seamRailSupportBoxes){
    const [width,height,depth]=part.size,id=api.addMesh('box',{width,height,depth});
    created.push(id);
    host.renameSceneObject(id,prefix+part.name);
    const world=new Vector3(...part.position).multiply(new Vector3(...scale)).applyEuler(new Euler(...rotation)).add(new Vector3(...position));
    host.kaminosSetSceneObjectTransform(id,{position:world.toArray(),rotation:[...rotation],scale:[...scale]});
    api.setWaterCollision(id,true);
    host.kaminosSceneVisibility.set(id,false);
    if(group)api.attach(id,group.id);
  }
  if(!group)group={id:api.group([railId,...created],'Slot burner')};
  return {railId,groupId:group.id,supportIds:created,approximation:'Ten separate boxes; bevels, fasteners and feed fitting omitted'};
}
